"""Expose only public verification data generated by this CI build for review."""
import base64
from pathlib import Path

for name in ('gradle/verification-metadata.xml', 'app/gradle.lockfile'):
    path = Path(name)
    if not path.is_file():
        raise SystemExit(f'Missing generated dependency verification: {name}')
    # Chunked log lines avoid runner/tool line limits. No credentials or environment.
    encoded = base64.b64encode(path.read_bytes()).decode()
    for offset in range(0, len(encoded), 4000):
        print(f'DEPENDENCY_FILE {name} {offset} {encoded[offset:offset+4000]}')
